/* ===========================================================
   Baylor Athletics — Applied Performance
   Multi-page report style. Charcoal header band, light body.
   Tokens follow the ShiftWave printed card (option-c-matrix.html):
     #1E1F1F charcoal · #154734 Baylor green · #FFB81C gold
     #AFD2C0 mint · #E0DDD1 bone
   Body is light so the sheet stays printable and writable.
   =========================================================== */

@page { size: Letter portrait; margin: 12mm 0 14mm; }

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { background: #4E5150; }

body {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
  background: #FFFFFF;
  color: #1E1F1F;
  font-family: 'DIN Pro', Arial, sans-serif;
  font-weight: 300;
  font-size: 10.6px;
  line-height: 1.52;
}

/* screen preview only — mimics a sheet */
@media screen {
  body { width: 8.5in; margin: 24px auto; box-shadow: 0 2px 24px rgba(0,0,0,.5); }
}

.wrap { padding: 0 16mm; }

/* ---------- HEADER BAND (page 1) ---------- */
.band {
  position: relative;
  background: #1E1F1F;
  border-bottom: 3px solid #FFB81C;
  padding: 20px 16mm 18px;
  overflow: hidden;
  margin-bottom: 16px;
}
.band::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(110% 60% at 80% 0%, rgba(21,71,52,.60), transparent 70%);
  pointer-events: none;
}
.band > * { position: relative; }

.plate {
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  margin-bottom: 14px;
}
.org { display: flex; align-items: center; gap: 11px; }
.bu {
  width: 29px; height: 29px;
  background-image: var(--bu-mark-white);
  background-size: contain; background-repeat: no-repeat; background-position: center;
}
.org-primary {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; font-size: 12px; letter-spacing: .2em;
  color: #FFFFFF; text-transform: uppercase;
}
.org-secondary {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 500; font-size: 8.8px; letter-spacing: .22em;
  color: #AFD2C0; text-transform: uppercase; margin-top: 3px;
}
.plate-title {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 500; font-size: 11.5px; letter-spacing: .26em;
  color: #E0DDD1; text-transform: uppercase; text-align: right;
}
.band h1.headline {
  font-family: 'Baylor Bears', 'DIN Pro Condensed', sans-serif;
  font-size: 40px; line-height: .93; letter-spacing: .005em;
  color: #FFFFFF; text-transform: uppercase; border: none; padding: 0; margin: 0;
}
.band h1.headline em { font-style: normal; color: #FFB81C; }
.band .sub {
  margin-top: 9px;
  font-family: 'DIN Pro Condensed', sans-serif;
  font-size: 11px; letter-spacing: .13em; text-transform: uppercase;
  color: #AFD2C0;
}

/* ---------- CONFIDENTIAL FLAG ---------- */
.warn {
  background: #7A1414; color: #FFFFFF;
  border-left: 4px solid #FFB81C;
  padding: 9px 13px; margin: 0 0 15px;
  font-size: 10.4px; line-height: 1.45;
  break-inside: avoid;
}
.warn strong {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; letter-spacing: .16em; text-transform: uppercase;
  color: #FFB81C;
}

/* ---------- HEADINGS ---------- */
h1 {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; font-size: 20px; letter-spacing: .05em;
  color: #154734; text-transform: uppercase;
  border-top: 2px solid #FFB81C;
  padding-top: 9px; margin: 22px 0 10px;
  break-after: avoid; break-inside: avoid;
}
h2 {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; font-size: 14.5px; letter-spacing: .09em;
  color: #154734; text-transform: uppercase;
  border-top: 2px solid #FFB81C;
  padding-top: 8px; margin: 19px 0 9px;
  break-after: avoid; break-inside: avoid;
}
h3 {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; font-size: 11px; letter-spacing: .18em;
  color: #1E1F1F; text-transform: uppercase;
  border-bottom: 1px solid rgba(255,184,28,.75);
  padding-bottom: 4px; margin: 16px 0 8px;
  break-after: avoid; break-inside: avoid;
}

p { margin: 0 0 8px; }
strong, b { font-weight: 500; color: #1E1F1F; }
em { font-style: italic; }
code {
  font-family: 'SF Mono', Menlo, Consolas, monospace;
  font-size: 9.4px; background: #F1F3F0; color: #154734;
  padding: 1px 4px; border-radius: 2px;
}
hr { border: none; border-top: 2px solid #FFB81C; margin: 18px 0 0; }
a { color: #154734; }

/* ---------- LISTS ---------- */
ul, ol { margin: 0 0 9px 17px; }
li { margin-bottom: 5px; }
li::marker { color: #154734; font-weight: 500; }

/* ---------- TABLES ---------- */
table {
  width: 100%; border-collapse: collapse;
  margin: 4px 0 12px;
  font-size: 10px;
  break-inside: auto;
}
thead { display: table-header-group; }
tr { break-inside: avoid; page-break-inside: avoid; }
th {
  font-family: 'DIN Pro Condensed', sans-serif;
  font-weight: 700; font-size: 9px; letter-spacing: .17em;
  text-transform: uppercase; color: #154734;
  text-align: left; vertical-align: bottom;
  padding: 5px 8px;
  background: rgba(21,71,52,.07);
  border-bottom: 2px solid #FFB81C;
}
td {
  padding: 6px 8px;
  vertical-align: top;
  border-bottom: 1px solid rgba(21,71,52,.16);
  line-height: 1.45;
}
tbody tr:nth-child(even) td { background: rgba(21,71,52,.035); }

/* checkbox column in the milestone tables */
td:first-child { white-space: nowrap; }

/* ---------- CALLOUTS ---------- */
blockquote {
  border-left: 4px solid #FFB81C;
  background: #FCF7EA;
  padding: 10px 13px;
  margin: 10px 0 13px;
  break-inside: avoid;
}
blockquote p { margin-bottom: 6px; }
blockquote p:last-child { margin-bottom: 0; }
blockquote strong { color: #154734; }

/* ---------- ASCII DEPENDENCY DIAGRAM ---------- */
pre {
  font-family: 'SF Mono', Menlo, Consolas, monospace;
  font-size: 9.6px; line-height: 1.4;
  background: #1E1F1F; color: #E0DDD1;
  border-left: 4px solid #FFB81C;
  padding: 12px 14px; margin: 10px 0 13px;
  overflow: hidden; white-space: pre;
  break-inside: avoid;
}
pre code { background: none; color: inherit; padding: 0; font-size: inherit; }

/* ---------- FOOTER ---------- */
.foot {
  margin-top: 20px;
  border-top: 2px solid #FFB81C;
  padding: 8px 0 0;
  display: flex; justify-content: space-between; align-items: baseline;
  font-family: 'DIN Pro Condensed', sans-serif;
  font-size: 8.6px; letter-spacing: .19em; text-transform: uppercase;
  color: #154734;
  break-inside: avoid;
}
.foot .r { color: #6B706C; }

/* ---------- PAGE BREAKS ---------- */
.pagebreak { break-before: page; page-break-before: always; }

